function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function sanitizeText(value, maxLength = 120) {
  return String(value || '').trim().slice(0, maxLength);
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
}

function normalizeUsername(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9._-]/g, '')
    .slice(0, 32);
}

function isMasterRole(role) {
  return ['owner', 'master'].includes(String(role || '').toLowerCase());
}

function normalizeAccountRole(role) {
  return isMasterRole(role) ? 'master' : 'instructor';
}

function adminActivityAnchor(admin) {
  return admin?.activity_anchor_at || admin?.activityAnchorAt || admin?.last_login_at || admin?.lastLoginAt || admin?.created_at || admin?.createdAt || new Date().toISOString();
}

function adminLifecycle(admin, nowMs = Date.now()) {
  if (isMasterRole(admin?.role)) {
    return { managed: false, phase: 'exempt', label: 'Sem expiração automática' };
  }
  const parsed = new Date(adminActivityAnchor(admin)).getTime();
  const anchorMs = Number.isFinite(parsed) ? parsed : nowMs;
  const inactivityMs = anchorMs + INACTIVITY_DAYS * DAY_MS;
  const masterOnlyMs = anchorMs + MASTER_ONLY_REACTIVATION_DAYS * DAY_MS;
  const deletionMs = anchorMs + PROFILE_DELETION_DAYS * DAY_MS;
  const inactiveReason = String(admin?.inactivity_reason || admin?.inactivityReason || '');
  let phase = 'active';
  if (!admin?.active && inactiveReason === 'manual') phase = 'manual_block';
  else if (nowMs >= deletionMs) phase = 'deletion_due';
  else if (nowMs >= masterOnlyMs) phase = 'master_only';
  else if (nowMs >= inactivityMs) phase = 'self_reactivation';
  return {
    managed: true,
    phase,
    anchorAt: new Date(anchorMs).toISOString(),
    inactivityAt: new Date(inactivityMs).toISOString(),
    masterOnlyAt: new Date(masterOnlyMs).toISOString(),
    deletionAt: new Date(deletionMs).toISOString(),
    daysToInactive: Math.max(0, Math.ceil((inactivityMs - nowMs) / DAY_MS)),
    daysToMasterOnly: Math.max(0, Math.ceil((masterOnlyMs - nowMs) / DAY_MS)),
    daysToDelete: Math.max(0, Math.ceil((deletionMs - nowMs) / DAY_MS)),
    canSelfReactivate: nowMs >= inactivityMs && nowMs < masterOnlyMs && inactiveReason === 'inactivity',
    inactivityReason: inactiveReason,
  };
}

function normalizeProfilePhoto(value) {
  const dataUrl = String(value || '').trim();
  if (!dataUrl) return '';
  const match = dataUrl.match(/^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/);
  if (!match) {
    const error = new Error('Envie uma foto JPG, PNG ou WEBP válida.');
    error.code = 'INVALID_PHOTO';
    throw error;
  }
  const estimatedBytes = Math.floor((match[2].length * 3) / 4);
  if (estimatedBytes > MAX_PROFILE_PHOTO_BYTES) {
    const error = new Error('A foto ficou muito grande. Escolha outra imagem.');
    error.code = 'PHOTO_TOO_LARGE';
    throw error;
  }
  return dataUrl;
}

function usernameBaseFrom(name, email) {
  const fromName = normalizeUsername(String(name || '').replace(/\s+/g, '.'));
  const fromEmail = normalizeUsername(String(email || '').split('@')[0]);
  return (fromName || fromEmail || 'usuario').slice(0, 24);
}

function generateTemporaryPassword() {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  const bytes = crypto.randomBytes(5);
  let randomPart = '';
  for (let index = 0; index < bytes.length; index += 1) randomPart += alphabet[bytes[index] % alphabet.length];
  return `Nz${randomPart}7`;
}

function temporaryPasswordVaultKey() {
  return crypto.createHash('sha256').update(PASSWORD_VAULT_SECRET).digest();
}

function encryptTemporaryPassword(password) {
  const plain = String(password || '');
  if (!plain) return '';
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', temporaryPasswordVaultKey(), iv);
  const encrypted = Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return ['v1', iv.toString('base64'), tag.toString('base64'), encrypted.toString('base64')].join('.');
}

function decryptTemporaryPassword(encoded) {
  try {
    const [version, ivValue, tagValue, encryptedValue] = String(encoded || '').split('.');
    if (version !== 'v1' || !ivValue || !tagValue || !encryptedValue) return '';
    const decipher = crypto.createDecipheriv('aes-256-gcm', temporaryPasswordVaultKey(), Buffer.from(ivValue, 'base64'));
    decipher.setAuthTag(Buffer.from(tagValue, 'base64'));
    return Buffer.concat([decipher.update(Buffer.from(encryptedValue, 'base64')), decipher.final()]).toString('utf8');
  } catch (error) {
    return '';
  }
}

