  async applyInstructorLifecycle(now = new Date()) {
    const nowMs = now.getTime();
    const inactivityCutoff = new Date(nowMs - INACTIVITY_DAYS * DAY_MS);
    const deletionCutoff = new Date(nowMs - PROFILE_DELETION_DAYS * DAY_MS);
    if (this.mode === 'postgres') {
      const deleted = await this.pool.query(
        `DELETE FROM quiz_admins
         WHERE LOWER(role) NOT IN ('master','owner')
           AND COALESCE(activity_anchor_at, last_login_at, created_at) <= $1
         RETURNING id`,
        [deletionCutoff],
      );
      const inactivated = await this.pool.query(
        `UPDATE quiz_admins
         SET active = FALSE, inactivity_reason = 'inactivity', inactive_at = COALESCE(inactive_at, NOW())
         WHERE LOWER(role) NOT IN ('master','owner')
           AND active = TRUE
           AND COALESCE(activity_anchor_at, last_login_at, created_at) <= $1
         RETURNING id`,
        [inactivityCutoff],
      );
      return { deletedIds: deleted.rows.map((row) => row.id), inactivatedIds: inactivated.rows.map((row) => row.id) };
    }
    const deletedIds = [];
    const inactivatedIds = [];
    for (const [id, admin] of this.admins) {
      if (isMasterRole(admin.role)) continue;
      const anchorMs = new Date(adminActivityAnchor(admin)).getTime();
      const effectiveAnchor = Number.isFinite(anchorMs) ? anchorMs : nowMs;
      if (effectiveAnchor <= deletionCutoff.getTime()) {
        this.admins.delete(id);
        deletedIds.push(id);
        continue;
      }
      if (effectiveAnchor <= inactivityCutoff.getTime() && admin.active) {
        admin.active = false;
        admin.inactivity_reason = 'inactivity';
        admin.inactive_at = admin.inactive_at || now.toISOString();
        inactivatedIds.push(id);
      }
    }
    return { deletedIds, inactivatedIds };
  }

