  async saveQuiz(rawQuiz, admin) {
    const quiz = normalizeQuiz(rawQuiz);
    const existing = await this.getQuiz(quiz.id);
    if (existing && admin.id !== 'system' && !isMasterRole(admin.role) && existing.ownerAdminId !== admin.id) {
      const error = new Error('Você só pode editar quizzes criados por você.');
      error.code = 'FORBIDDEN';
      throw error;
    }
    const now = new Date().toISOString();
    const record = {
      ...quiz,
      ownerAdminId: existing?.ownerAdminId || admin.id,
      ownerName: existing?.ownerName || admin.name,
      createdAt: existing?.createdAt || now,
      updatedAt: now,
    };
    if (this.mode === 'postgres') {
      await this.pool.query(
        `INSERT INTO quizzes (id, owner_admin_id, owner_name, title, description, cover_image, music_theme, questions, created_at, updated_at)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,NOW(),NOW())
         ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, cover_image=EXCLUDED.cover_image,
         music_theme=EXCLUDED.music_theme, questions=EXCLUDED.questions, updated_at=NOW()`,
        [record.id, record.ownerAdminId, record.ownerName, record.title, record.description, record.coverImage || null, record.musicTheme, JSON.stringify(record.questions)],
      );
    } else {
      this.quizzes.set(record.id, record);
    }
    return record;
  }

