    if (body.adminId === session.admin.id) return json(res, 400, { ok: false, message: 'Você não pode bloquear seu próprio acesso.' });
    const targetId = sanitizeText(body.adminId, 120);
    const target = await store.getAdminById(targetId);
    if (!target) return json(res, 404, { ok: false, message: 'Usuário não encontrado.' });
    await store.updateAdminStatus(targetId, Boolean(body.active));
    for (const [token, activeSession] of adminSessions) if (activeSession.admin?.id === targetId) adminSessions.delete(token);
    const updated = await store.getAdminById(targetId);
